import{_t as e,it as t,n,rt as r}from"./chunks/framework.BmT8T0yb.js";var i=JSON.parse(`{"title":"Plan View","description":"","frontmatter":{"qt_version":"6.12.0"},"headers":[],"relativePath":"en/qgc-user-guide/plan_view/plan_view.md","filePath":"en/qgc-user-guide/plan_view/plan_view.md"}`),a={name:`en/qgc-user-guide/plan_view/plan_view.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="plan-view" tabindex="-1">Plan View <a class="header-anchor" href="#plan-view" aria-label="Permalink to “Plan View”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Having trouble?</p><p>If missions fail to upload or download, see <a href="./../troubleshooting/plan_upload_download.html">Plan Upload/Download Failures</a>. For mission resume issues, see <a href="./../troubleshooting/resume_mission.html">Resume Mission Failures</a>.</p></div><p>The <em>Plan View</em> is used to plan <em>autonomous missions</em> for your vehicle, and upload them to the vehicle. Once the mission is <a href="#plan-mission">planned</a> and sent to the vehicle, you switch to the <a href="./../fly_view/fly_view.html">Fly View</a> to fly the mission.</p><p>It is also used to configure the <a href="./plan_geofence.html">GeoFence</a> and <a href="./plan_rally_points.html">Rally Points</a> if these are supported by the firmware.</p><h2 id="ui_overview" tabindex="-1">UI Overview <a class="header-anchor" href="#ui_overview" aria-label="Permalink to “UI Overview”">​</a></h2><p>The main elements of the UI are:</p><ul><li><strong>Map:</strong> Displays the numbered indicators for the current mission, including the <a href="#planned-home">Planned Home</a>. Click on the indicators to select them (for editing) or drag them around to reposition them. Flight path lines and direction arrows show the planned route between waypoints.</li><li><strong>Plan Toolbar:</strong> Located at the top of the view with buttons for <strong>Open</strong>, <strong>Save</strong>, <strong>Upload</strong>, and <strong>Clear</strong>. A hamburger menu (☰) provides additional options such as <em>Save as KML</em> and <em>Download</em> (load plan from vehicle). The <strong>Save</strong> and <strong>Upload</strong> buttons are highlighted when there are unsaved or un-uploaded changes.</li><li><strong><a href="#plan-tools">Plan Tools</a>:</strong> A vertical tool strip on the left side of the map used to add mission items (Takeoff, Waypoint, Pattern, ROI, Return/Land) and toggle the stats panel.</li><li><strong><a href="#plan-editor-panel">Plan Editor Panel</a>:</strong> A tabbed panel on the right side with <strong>Plan</strong>, <strong>Mission</strong>, <strong>Fence</strong>, and <strong>Rally</strong> tabs containing the plan settings and the mission item, GeoFence, and rally point editors. The selected tab also sets what is edited on the map.</li><li><strong>Mission Stats / Terrain Panel:</strong> A panel at the bottom of the map that can toggle between a terrain altitude profile chart (height AMSL vs. distance) and mission statistics (selected waypoint info, total distance, max telemetry distance, estimated flight time, and battery info).</li></ul><h2 id="plan_mission" tabindex="-1">Planning a Mission <a class="header-anchor" href="#plan_mission" aria-label="Permalink to “Planning a Mission”">​</a></h2><p>At a very high level, the steps to create a mission are:</p><ol><li>Change to <em>Plan View</em>.</li><li>Add waypoints or commands to the mission and edit as needed.</li><li>Upload the mission to the vehicle.</li><li>Change to <em>Fly View</em> and fly the mission.</li></ol><p>The following sections explain some of the details in the view.</p><h2 id="planned_home" tabindex="-1">Planned Home Position <a class="header-anchor" href="#planned_home" aria-label="Permalink to “Planned Home Position”">​</a></h2><p>The <em>Planned Home</em> shown in <em>Plan View</em> is used to set the approximate start point when planning a mission (i.e. when a vehicle may not even be connected to QGC). It is used by QGC to estimate mission times and to draw waypoint lines.</p><p>Set the planned home position by clicking in the map while the <strong>Plan</strong> tab of the <a href="#plan-editor-panel">Plan Editor Panel</a> is selected. You should move/drag the planned home position to roughly the location where you plan to takeoff. The altitude for the planned home position is determined automatically from terrain data.</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>The Fly View displays the <em>actual</em> home position set by the vehicle firmware when it arms (this is where the vehicle will return in Return/RTL mode).</p></div><h2 id="plan_tools" tabindex="-1">Plan Tools <a class="header-anchor" href="#plan_tools" aria-label="Permalink to “Plan Tools”">​</a></h2><p>The plan tools are a vertical tool strip on the left side of the map, used for adding mission items. The tools are only visible while the <strong>Mission</strong> tab of the <a href="#plan-editor-panel">Plan Editor Panel</a> is selected. The main tools (top to bottom) are described below.</p><h3 id="takeoff" tabindex="-1">Takeoff <a class="header-anchor" href="#takeoff" aria-label="Permalink to “Takeoff”">​</a></h3><p>Inserts a takeoff command into the mission. This tool is available for all vehicle types except rovers.</p><p>For PX4 VTOL vehicles, choose <strong>VTOL takeoff</strong> to climb and transition to fixed-wing flight, or <strong>Multicopter takeoff</strong> to remain in multicopter mode. The VTOL takeoff remains the default choice.</p><h3 id="pattern" tabindex="-1">Pattern <a class="header-anchor" href="#pattern" aria-label="Permalink to “Pattern”">​</a></h3><p>The <a href="./pattern.html">Pattern</a> tool simplifies the creation of missions for flying complex geometries, including <a href="./../plan_view/pattern_survey.html">surveys</a> and <a href="./../plan_view/pattern_structure_scan_v2.html">structure scans</a>. If multiple pattern types are available for the vehicle, clicking the button opens a dropdown to select from Survey, Corridor Scan, Structure Scan, and landing patterns.</p><h3 id="waypoint" tabindex="-1">Waypoint <a class="header-anchor" href="#waypoint" aria-label="Permalink to “Waypoint”">​</a></h3><p>Click the <strong>Waypoint</strong> tool to toggle waypoint-on-click mode. While active, clicking on the map will add a new mission waypoint at the clicked location. The tool stays active until you click it again to deactivate. Once you have added a waypoint, you can select it and drag it around to reposition it.</p><h3 id="roi" tabindex="-1">ROI <a class="header-anchor" href="#roi" aria-label="Permalink to “ROI”">​</a></h3><p>Toggles Region of Interest mode. When active, clicking on the map sets an ROI location. This tool is only visible if the vehicle firmware supports ROI mode.</p><h3 id="return-land" tabindex="-1">Return / Land <a class="header-anchor" href="#return-land" aria-label="Permalink to “Return / Land”">​</a></h3><p>Adds a return or land command to the mission. The label varies by vehicle type:</p><ul><li><strong>Multicopters:</strong> <em>Return</em></li><li><strong>Fixed-wing:</strong> <em>Land</em> (or <em>Alt Land</em> if a land item already exists in the mission)</li></ul><h3 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to “Stats”">​</a></h3><p>Toggles the <a href="#stats-terrain">Mission Stats / Terrain panel</a> at the bottom of the map. Only visible when that panel is currently hidden.</p><h2 id="file" tabindex="-1">File Operations <a class="header-anchor" href="#file" aria-label="Permalink to “File Operations”">​</a></h2><p>File operations are located in the <strong>Plan Toolbar</strong> at the top of the view:</p><ul><li><strong>Open</strong> — Load a plan from a file.</li><li><strong>Save</strong> — Save the current plan to a file. Highlighted when there are unsaved changes.</li><li><strong>Upload</strong> — Upload the plan to the vehicle. Highlighted when the plan has un-uploaded changes.</li><li><strong>Clear</strong> — Remove all mission items, geofence, and rally points. If connected to a vehicle, also clears them from the vehicle.</li><li><strong>Hamburger menu</strong> (☰) — Additional options: <ul><li><em>Save as...</em> — Save the plan to a new file.</li><li><em>Save as KML</em> — Export the plan as a KML file.</li><li><em>Download</em> — Download the current plan from the vehicle (only available when connected).</li></ul></li></ul><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Before you fly a mission you must upload it to the vehicle.</p></div><h2 id="plan_editor_panel" tabindex="-1">Plan Editor Panel <a class="header-anchor" href="#plan_editor_panel" aria-label="Permalink to “Plan Editor Panel”">​</a></h2><p>The Plan Editor Panel is a tabbed panel on the right side of the view. The tabs are on its left edge: <strong>Plan</strong>, <strong>Mission</strong>, <strong>Fence</strong>, and <strong>Rally</strong>. On short screens the tab names are replaced by icons. The panel can be closed or opened using the toggle button at the bottom of its left edge.</p><p>The selected tab is also the active map editing layer: the map elements of the selected tab can be edited, and the others are dimmed.</p><ul><li>A new or empty plan opens on the <strong>Plan</strong> tab. A plan which has items opens on the <strong>Mission</strong> tab.</li><li>The <strong>Mission</strong>, <strong>Fence</strong>, and <strong>Rally</strong> tabs are disabled until the <a href="#planned-home">planned home position</a> is set.</li><li>A warning dot is shown on the <strong>Mission</strong> tab while the mission has incomplete items.</li></ul><p>The <strong>Mission</strong>, <strong>Fence</strong>, and <strong>Rally</strong> tabs show a list with an inspector for the selected entry below it. You can drag the divider between them to resize the list. On short screens the list and the inspector take turns filling the tab: selecting an entry opens its inspector, which has <strong>Back</strong>, <strong>Previous</strong>, and <strong>Next</strong> buttons.</p><h3 id="plan_info" tabindex="-1">Plan Tab <a class="header-anchor" href="#plan_info" aria-label="Permalink to “Plan Tab”">​</a></h3><p>The Plan tab contains the plan-level settings. While this tab is selected, clicking in the map sets the planned home position.</p><p>The <strong>Plan</strong> group shows:</p><ul><li><strong>File</strong> — The name of the currently loaded plan file (<code>&lt;Untitled&gt;</code> if the plan has not been saved yet).</li><li><strong>Firmware</strong> and <strong>Vehicle</strong> — Firmware and vehicle type selectors. When connected to a vehicle these are determined automatically; when planning offline you must set them before adding any mission items so that the correct mission commands are available.</li><li><strong>Home</strong> — Whether the planned home position is set, and its altitude (AMSL), which is determined automatically from terrain data. If terrain data is not available you can enter the altitude. This is only the <em>planned</em> home position for estimating mission times and drawing waypoint lines — the actual home position is set by the vehicle when it arms.</li></ul><h4 id="start-from-a-template" tabindex="-1">Start from a Template <a class="header-anchor" href="#start-from-a-template" aria-label="Permalink to “Start from a Template”">​</a></h4><p>For an empty plan, the <strong>Start from a template</strong> group offers buttons which create a plan for you, such as a survey. The buttons are enabled once the planned home position is set. Choose <strong>No Template</strong> to add the mission items yourself.</p><h4 id="defaults" tabindex="-1">Defaults <a class="header-anchor" href="#defaults" aria-label="Permalink to “Defaults”">​</a></h4><p>The <strong>Defaults</strong> group sets plan-wide values that apply to new mission items:</p><ul><li><strong>Alt Frame</strong> — Select the altitude reference frame for waypoints.</li><li><strong>Altitude</strong> — The default altitude for the first mission item added (subsequent items take their initial altitude from the previous item). Changing this value when items already exist will prompt to update all items to the new altitude.</li><li><strong>Flight Speed</strong> — Set a flight speed that differs from the default mission speed.</li><li><strong>Expected Vehicle Speeds</strong> — Cruise speed (fixed-wing) and/or hover, ascent, and descent speeds (multi-rotor/VTOL), used for estimating mission time. They do not affect the flight speed for the mission.</li></ul><h4 id="transform" tabindex="-1">Transform <a class="header-anchor" href="#transform" aria-label="Permalink to “Transform”">​</a></h4><p>The <strong>Transform mission...</strong> button in the <strong>Tools</strong> group opens a dialog with tools to adjust the entire mission after it has been created:</p><ul><li><strong>Offset Mission</strong> — Shift the mission by a specified distance in the East, North, and Up directions. Optionally include takeoff and/or landing items in the offset.</li><li><strong>Reposition Mission</strong> — Move the mission to a new location specified by geographic coordinates (Lat/Lon), UTM, MGRS, or the current vehicle position.</li><li><strong>Rotate Mission</strong> — Rotate the mission clockwise by a specified number of degrees. Optionally include takeoff and/or landing items in the rotation.</li></ul><h3 id="mission_items" tabindex="-1">Mission Tab <a class="header-anchor" href="#mission_items" aria-label="Permalink to “Mission Tab”">​</a></h3><p>The Mission tab lists all mission items (waypoints, commands, patterns, etc.) in order. The <a href="#plan-tools">Plan Tools</a> are shown while this tab is selected.</p><p>The line at the top of the tab shows the mission distance, the estimated flight time, and the number of incomplete items. The <strong>Alt</strong> button next to it shows the default altitude for new items; click it to open the <a href="#defaults">Defaults</a> on the Plan tab.</p><p>Each row of the list shows the item&#39;s sequence number, its command, and its altitude if it has one.</p><ul><li>Click a row, or the item on the map, to select the item and show its editor in the inspector.</li><li>Click <strong>Change...</strong> in the inspector to change the item type. A dialog shows &quot;Basic Commands&quot; by default; use the <strong>Category</strong> dropdown to see all available commands.</li><li>The inspector&#39;s <strong>hamburger menu</strong> (☰) has options such as <em>Show all values</em>, <em>Move to vehicle position</em>, <em>Move to previous item position</em>, and <em>Edit position</em>.</li><li>The <strong>delete button</strong> (trash icon) removes the item.</li><li>Items that are incomplete or missing required values show a <strong>?</strong> instead of their sequence number and are marked <em>Incomplete</em>.</li></ul><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>The list of available commands depends on firmware and vehicle type. Examples include: Waypoint, Start image capture, Jump to item (to repeat mission), and other commands.</p></div><h4 id="initial-camera-settings" tabindex="-1">Initial Camera Settings <a class="header-anchor" href="#initial-camera-settings" aria-label="Permalink to “Initial Camera Settings”">​</a></h4><p>The first row of the list (<strong>H</strong>) is the planned home position. Selecting it allows you to set camera options before any mission items take place. This includes camera actions (take photos by time/distance, start/stop video recording) and gimbal control.</p><h3 id="geofence" tabindex="-1">Fence Tab <a class="header-anchor" href="#geofence" aria-label="Permalink to “Fence Tab”">​</a></h3><p>The Fence tab allows you to define <a href="./plan_geofence.html">GeoFence</a> boundaries:</p><ul><li><strong>+ Polygon</strong> and <strong>+ Circle</strong> add a polygon or circular fence to the map and to the list.</li><li>Select a fence in the list to edit it on the map and in the inspector, where it can be switched between <em>Include</em> and <em>Exclude</em>, given a radius (circular fences), or deleted.</li><li><strong>Breach return point</strong> — Optionally set a return point (with altitude) that the vehicle will fly to if it breaches the geofence.</li></ul><h3 id="rally_points" tabindex="-1">Rally Tab <a class="header-anchor" href="#rally_points" aria-label="Permalink to “Rally Tab”">​</a></h3><p>The Rally tab displays and manages <a href="./plan_rally_points.html">Rally Points</a>. While this tab is selected, clicking in the map adds a rally point. When a rally point is selected, its position and altitude fields are shown in the inspector for editing.</p><h2 id="stats_terrain" tabindex="-1">Mission Stats / Terrain Panel <a class="header-anchor" href="#stats_terrain" aria-label="Permalink to “Mission Stats / Terrain Panel”">​</a></h2><p>A panel at the bottom of the map provides two toggleable views:</p><ul><li><strong>Terrain Profile</strong> — A chart showing height AMSL vs. distance from start across the mission.</li><li><strong>Mission Statistics</strong> — Displays details for the selected waypoint (altitude difference, azimuth, distance to previous waypoint, gradient, heading) and for the total mission (distance, max telemetry distance, estimated flight time). Battery information (batteries required and change point) is also shown when available.</li></ul><p>Toggle buttons on the left side of the panel let you switch between the terrain profile and mission statistics views, or collapse the panel entirely.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><h3 id="plan_transfer_fail" tabindex="-1">Mission (Plan) Upload/Download Failures <a class="header-anchor" href="#plan_transfer_fail" aria-label="Permalink to “Mission (Plan) Upload/Download Failures”">​</a></h3><p>Plan uploading and downloading can fail over a noisy communication link (affecting missions, GeoFence, and rally points). If a failure occurs you should see a status message in the QGC UI similar to:</p><blockquote><p>Mission transfer failed. Retry transfer. Error: Mission write mission count failed, maximum retries exceeded.</p></blockquote><p>The loss rate for your link can be viewed in <a href="./../settings_view/telemetry.html">App Settings &gt; Telemetry</a>. The loss rate should be in the low single digits (i.e. maximum of 2 or 3):</p><ul><li>A loss rate in the high single digits can lead to intermittent failures.</li><li>Higher loss rates often lead to 100% failure.</li></ul><p>There is a much smaller possibility that issues are caused by bugs in either flight stack or QGC. To analyze this possibility you can turn on <a href="./../troubleshooting/console_logging.html">Console Logging</a> for Plan upload/download and review the protocol message traffic.</p>`,76)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};